import { Component, EventEmitter, Output } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { Store } from '@ngrx/store';
import { ValidatorsService } from '../../services/validators.service';
import { ClearDataService } from '../../services/clear-data.service';
import { AttemptsSelectors, CustomerActions } from '../../store';

@Component({
  selector: 'app-identification-data',
  templateUrl: './identification-data.component.html',
  styleUrls: ['./identification-data.component.scss']
})
export class IdentificationDataComponent {

  canTry$ = this.store.select(AttemptsSelectors.canTry)

  identificationForm: FormGroup = new FormGroup({
    document: new FormControl('', [Validators.required, Validators.pattern('^[0-9]{5,10}$')]),
    complement: new FormControl('', Validators.pattern('^[A-Za-z0-9]{1,2}$')),
    extension: new FormControl(null, this.validatorsService.validateNullValue.bind(this.validatorsService)),
    birthday: new FormControl('', [Validators.required, this.validatorsService.validateBirthday.bind(this.validatorsService)])
  });

  extensionCatalog: { code: string; description: string }[] = [
    {
      code: '',
      description: 'SIN EXTENSIÓN'
    },
    {
      code: 'BE',
      description: 'BENI'
    },
    {
      code: 'CB',
      description: 'COCHABAMBA'
    },
    {
      code: 'CH',
      description: 'CHUQUISACA'
    },
    {
      code: 'LP',
      description: 'LA PAZ'
    },
    {
      code: 'OR',
      description: 'ORURO'
    },
    {
      code: 'PA',
      description: 'PANDO'
    },
    {
      code: 'PO',
      description: 'POTOSI'
    },
    {
      code: 'SC',
      description: 'SANTA CRUZ'
    },
    {
      code: 'TJ',
      description: 'TARIJA'
    }
  ]

  @Output()
  goToStepTwo: EventEmitter<boolean> = new EventEmitter();

  constructor(
    private store: Store,
    private validatorsService: ValidatorsService,
    private clearDataService: ClearDataService
  ) {
    // this.identificationForm.patchValue({ document: '4787798', extension: '', birthday: '1980-03-17' })
  }

  onSubmit(): void {
    if (!this.identificationForm.valid) {
      this.identificationForm.markAllAsTouched();
      return;
    }
    const formData = {
      identification: this.identificationForm.get('document')?.value
                    + this.identificationForm.get('complement')?.value
                    + this.identificationForm.get('extension')?.value,
      birthdate: this.clearDataService.formatDateString(this.identificationForm.get('birthday')?.value),
    }
    this.store.dispatch(CustomerActions.loadUserInfo(this.clearDataService.cleanData(formData)))
    this.identificationForm.reset({ document: '', complement: '', extension: null, birthday: '' });
  }

}
