import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { HttpErrorResponse } from '@angular/common/http';
import { Store } from '@ngrx/store';
import { Actions, concatLatestFrom, createEffect, ofType } from '@ngrx/effects';
import { of } from 'rxjs';
import { catchError, concatMap, finalize, map, mergeMap, tap } from 'rxjs/operators';
import { TokenActions } from '../../../shared/store';
import { AttemptsActions, CustomerActions, CustomerSelectors } from '..';
import { SnackBarService } from '../../../shared/services/snack-bar.service';
import { StepperService } from '../../services/stepper.service';
import { IdentityVerifyService } from '../../services/identity-verify.service';
import { ReCaptchaV3Service } from 'ng-recaptcha';

@Injectable()
export class CustomerEffects {

  constructor(
    private store: Store,
    private actions$: Actions,
    private router: Router,
    private identityVerifyService: IdentityVerifyService,
    private reCaptchaV3Service: ReCaptchaV3Service,
    private snackBarService: SnackBarService,
    private stepperService: StepperService
  ) { }

  loadUserInfo$ = createEffect(() => this.actions$.pipe(
    ofType(CustomerActions.loadUserInfo),
    concatMap(({ identification, birthdate }) => this.reCaptchaV3Service.execute('submit').pipe(
      concatMap(token => this.identityVerifyService.validateClient(identification, birthdate, token).pipe(
        map(maskedCustomerInfo => {
          this.stepperService.nextStep();
          return CustomerActions.loadUserInfoSuccess({ customer: maskedCustomerInfo })
        }),
        catchError((httpError: HttpErrorResponse) => {
          this.stepperService.reset();
          if (httpError.status === 400) this.store.dispatch(AttemptsActions.incremetAttempts());
          return of(CustomerActions.loadUserInfoFailure(
            httpError.status === 500 ? { error: httpError.error.cause } : { error: httpError.error.message }
          ));
        }),
        finalize(() => this.store.dispatch(CustomerActions.resetError()))
      ))
    ))
  ));

  sendOtpCode$ = createEffect(() => this.actions$.pipe(
    ofType(CustomerActions.sendCode),
    concatLatestFrom(() => this.store.select(CustomerSelectors.customer)),
    mergeMap(([action, customer]) => this.identityVerifyService.sendCode(customer?.userCode!).pipe(
      map(() => CustomerActions.successSendCode()),
      catchError((httpError: HttpErrorResponse) => of(CustomerActions.loadUserInfoFailure({ error: httpError.error.message }))),
      finalize(() => this.store.dispatch(CustomerActions.resetError()))
    ))
  ));

  validateCode$ = createEffect(() => this.actions$.pipe(
    ofType(CustomerActions.validateOtpCode),
    concatLatestFrom(() => this.store.select(CustomerSelectors.customer)),
    mergeMap(([action, customer]) => this.identityVerifyService.validateCode(customer?.userCode!, action.otpCode).pipe(
      map(accessToken => {
        this.router.navigateByUrl('/dashboard/my-insurance');
        this.store.dispatch(CustomerActions.resetUserInfo());
        this.store.dispatch(AttemptsActions.resetAttempts());
        this.store.dispatch(AttemptsActions.resetOtpAttempts());
        this.snackBarService.openSnackBar('¡Validación exitosa!')
        return TokenActions.saveToken({ token: accessToken });
      }),
      catchError((httpError: HttpErrorResponse) => {
        if( httpError.status === 400 ) {
          this.store.dispatch(AttemptsActions.incrementOtpAttempts());
          return of(CustomerActions.loadUserInfoFailure({ error: 'EL CÓDIGO OTP INGRESADO ES INCORRECTO. POR FAVOR, INTÉNTELO DE NUEVO.' }))
        }
        return of(CustomerActions.loadUserInfoFailure({ error: httpError.error.message }))
      }),
      finalize(() => this.store.dispatch(CustomerActions.resetError()))
    ))
  ));

  loadFailure$ = createEffect(() => this.actions$.pipe(
    ofType(CustomerActions.loadUserInfoFailure),
    tap(({ error }) => {
      this.snackBarService.openSnackBar(error ? error : 'EL SERVICIO SOLICITADO NO SE ENCUENTRA DISPONIBLE, POR FAVOR INTENTE MAS TARDE.')
    })
  ), { dispatch: false });


}

