import { Injectable } from "@angular/core";
import { Store } from "@ngrx/store";
import { Actions, createEffect, ofType } from "@ngrx/effects";
import { map, switchMap, tap, withLatestFrom } from "rxjs";
import { LocalStorageService } from '../../../shared/services/local-storage.service';
import { AttemptsActions, AttemptsSelectors } from "..";
import { InitAppService } from '../../../shared/services/init-app.service';

@Injectable()
export class AttemptsEffects {

  constructor( private actions$: Actions, private store: Store, private localStorageService: LocalStorageService, private initAppService: InitAppService ) {}

  loadAttempts$ = createEffect(() => this.actions$.pipe(
    ofType(AttemptsActions.loadAttempts),
    switchMap( () => this.localStorageService.getObsLocalStorageFromKey( this.localStorageService.attemptsStorageKey, true ).pipe(
      map( ( attemptsLsData ) => {
        if( !attemptsLsData ) return AttemptsActions.attemptsLoaded({ attempts: 0 });
        const { attempts, date } = attemptsLsData;
        if( attempts < this.initAppService.constants.attemptsAllowed ) return AttemptsActions.attemptsLoaded({ attempts });
        const oneHourInMillis = this.initAppService.constants.inactivationTimeSeconds * 1000;
        const hasOneHourPassed = new Date().getTime() - (date as unknown as number) > oneHourInMillis;
        return hasOneHourPassed
          ? AttemptsActions.attemptsLoaded({ attempts: 0 })
          : AttemptsActions.attemptsLoaded({ attempts: 3 });
      }),
    ))
  ));

  incremetAttempts$ = createEffect(() =>
    this.actions$.pipe(
      ofType(AttemptsActions.incremetAttempts),
      withLatestFrom(this.store.select(AttemptsSelectors.attempts)),
      tap(([action, attempts]) => this.localStorageService.saveToLocalStorage(this.localStorageService.attemptsStorageKey, { attempts, date: new Date().getTime() }))
    ),
    { dispatch: false } // Indica que este efecto no despacha una acción
  );

  resetAttempts$ = createEffect(() =>
    this.actions$.pipe(
      ofType(AttemptsActions.resetAttempts),
      withLatestFrom(this.store.select(AttemptsSelectors.attempts)),
      tap(() => this.localStorageService.removeItemLocalStorage(this.localStorageService.attemptsStorageKey))
    ),
    { dispatch: false } // Indica que este efecto no despacha una acción
  );

}
