import { Component, OnInit } from '@angular/core';
import { Store } from '@ngrx/store';
import { AttemptsActions, CustomerActions } from '../../store';
import { canTryOtp } from '../../store/selectors/attempts.selectors';
import { DialogService } from '../../../shared/services/dialog.service';
import { StepperService } from '../../services/stepper.service';

@Component({
  selector: 'app-otp-validate',
  templateUrl: './otp-validate.component.html',
  styleUrls: ['./otp-validate.component.scss']
})
export class OtpValidateComponent implements OnInit {

  private otpRegex = new RegExp('^\\d{6}$');
  otpCode: string = '';
  isValidCode: boolean = true;
  clickAttempts: number = 0;

  canTryOtp$ = this.store.select( canTryOtp );

  constructor( private store: Store, private dialogService: DialogService, private stepperService: StepperService ) { }

  ngOnInit(): void {
    this.canTryOtp$.subscribe( canTryOtp => {
      if( canTryOtp ) return;
      this.dialogService.openDialog({
        title: '¡Atención!',
        message: 'Has alcanzado el límite de intentos permitidos con el OTP. Por favor, inténtalo más tarde.',
        acceptButton: true,
        cancelButton: false
      }).subscribe( result => {
        this.stepperService.reset();
        for (let i = 0; i < 3; i++) { this.store.dispatch(AttemptsActions.incremetAttempts()) }
      })
    })
  }

  onCodeChanged(code: string) {
    this.otpCode = code;
    this.validateOtpCode();
  }

  onCodeCompleted(code: string) {
    this.otpCode = code;
    this.validateOtpCode();
  }

  onVerifyCode() {
    this.clickAttempts++;
    this.validateOtpCode();
    if( !this.isValidCode ) return;
    this.store.dispatch( CustomerActions.validateOtpCode({ otpCode: this.otpCode }) );
  }

  validateOtpCode() {
    if( this.otpRegex.test(this.otpCode) ) {
      this.isValidCode = true;
      return;
    }
    this.isValidCode = false;
  }

}


