import { Component, EventEmitter, OnDestroy, OnInit, Output } from '@angular/core';
import { Store } from '@ngrx/store';
import { DialogService } from '../../../shared/services/dialog.service';
import { CustomerSelectors } from '../../store';
import { Subscription } from 'rxjs';
import { LoaderSelectors } from '../../../shared/store';
import { CountdownService } from '../../../shared/services/countdown.service';

@Component({
  selector: 'app-check-information',
  templateUrl: './check-information.component.html',
  styleUrls: ['./check-information.component.scss']
})
export class CheckInformationComponent implements OnInit, OnDestroy {

  @Output()
  goToStepThree: EventEmitter<boolean> = new EventEmitter();
  loader$ = this.store.select( LoaderSelectors.loader );
  customerSubs!: Subscription;

  fullName?: string;
  surname?: string;
  secondSurname?: string;
  identification?: string;

  counter: number = 5;

  constructor(
    private store: Store,
    private dialogService: DialogService,
    private countdownService: CountdownService
  ) { }

  ngOnInit(): void {
    this.customerSubs = this.store.select( CustomerSelectors.customer ).subscribe( maskedCustomerInfo => {
      this.fullName = maskedCustomerInfo?.firstName! + (maskedCustomerInfo?.middleName ? (' ' + maskedCustomerInfo?.middleName) : '' );
      this.surname = maskedCustomerInfo?.surname;
      this.secondSurname = maskedCustomerInfo?.secondSurname;
      this.identification = maskedCustomerInfo?.identification;
    });

    this.countdownService.startCountdown( this.counter ).subscribe({
      next: value => this.counter = value
    });
  }

  ngOnDestroy(): void {
    this.customerSubs.unsubscribe();
  }

  public onCheck( correct: boolean ): void {
    if(!correct) {
      this.dialogService.openDialog({
        title: '¡Aviso!',
        message: 'Por favor, introduzca sus datos correctamente e inténtelo de nuevo.',
        acceptButton: true,
        cancelButton: false
      }).subscribe( _ => {
        this.goToStepThree.emit(correct);
      })
      return;
    }
    this.goToStepThree.emit(correct);
  }
}
