import { AfterViewInit, Component , OnInit, ViewChild } from '@angular/core';
import { StepperOrientation, MatStepper } from '@angular/material/stepper';
import { BreakpointObserver } from '@angular/cdk/layout';
import { STEPPER_GLOBAL_OPTIONS } from '@angular/cdk/stepper';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { Store } from '@ngrx/store';
import { CustomerActions } from './store';
import { StepperService } from './services/stepper.service';

@Component({
  selector: 'app-verify-identity',
  templateUrl: './verify-identity.component.html',
  styleUrls: ['./verify-identity.component.scss'],
  providers: [
    {
      provide: STEPPER_GLOBAL_OPTIONS,
      useValue: { displayDefaultIndicatorType: false },
    },
  ],
})
export class VerifyIdentityComponent implements AfterViewInit {

  @ViewChild('stepper', { static: false }) stepper!: MatStepper;
  stepperOrientation: Observable<StepperOrientation>;

  constructor( private store: Store, public breakpointObserver: BreakpointObserver, private stepperService: StepperService) {
    this.stepperOrientation = breakpointObserver
      .observe('(min-width: 800px)')
      .pipe(map(({matches}) => (matches ? 'horizontal' : 'vertical')));
  }

  ngAfterViewInit(): void {
    this.stepperService.setStepper(this.stepper);
  }

  nextStep( next: boolean ): void {
    if ( next ) {
      this.stepper.next();
      return;
    }
    this.store.dispatch( CustomerActions.resetUserInfo() );
    this.stepper.reset();
  }

}
