import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Observable, delay, map, tap, throwError, } from 'rxjs';
import { SendCodeRequest,
         ValidateClientRequest,
         ValidateCodeRequest,
         MaskedCustomerInfo,
         ValidateCLientResponse,
         ValidateCodeResponse} from '../interfaces';
import { BaseResponse } from '../../shared/interface';
import { environment } from '../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class IdentityVerifyService {

  private baseApiUrl = environment.API_ENDPOINT + environment.INSURANCE_AUTH_API;

  constructor( private http: HttpClient ) {}

  validateClient( document: string, birthdate: string, token: string ): Observable<MaskedCustomerInfo> {
    const body: ValidateClientRequest = {
      document,
      birthDate: birthdate,
      token
    };

    return this.http.post<BaseResponse<ValidateCLientResponse>>( this.baseApiUrl + '/validateClient', body).pipe(
      map( resp => resp.result.maskedCustomerInfo )
    );
  }

  sendCode( userCode: string ) {
    const body: SendCodeRequest = { userCode: userCode };
    return this.http.post<BaseResponse<any>>(this.baseApiUrl + '/sendCode', body)
      .pipe(
        delay(3000)
      )
  }

  validateCode( userCode: string, otpCode: string ):Observable<string> {
    const body: ValidateCodeRequest = {
      userCode: userCode,
      code: otpCode
    }
    return this.http.post<BaseResponse<ValidateCodeResponse>>( this.baseApiUrl + '/validateCode', body ).pipe(
      map( resp => resp.result.authInfo.accessToken )
    );
  }



}
