import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { Store } from '@ngrx/store';
import { AttemptsActions, CustomerActions, CustomerSelectors } from '../../store';
import { DialogService } from '../../../shared/services/dialog.service';
import { CountdownService } from '../../../shared/services/countdown.service';

@Component({
  selector: 'app-check-phone',
  templateUrl: './check-phone.component.html',
  styleUrls: ['./check-phone.component.scss']
})
export class CheckPhoneComponent implements OnInit {

  @Output() goToStepFour: EventEmitter<boolean> = new EventEmitter();
  customer$ = this.store.select( CustomerSelectors.customer );

  counter: number = 5;

  constructor(
    private store: Store,
    private dialogService: DialogService,
    private countdownService: CountdownService
  ) {}

  ngOnInit(): void {
    this.countdownService.startCountdown( this.counter ).subscribe({
      next: value => this.counter = value
    });
  }

  onCheck( correct: boolean ): void {
    if( !correct ) {
      this.dialogService.openDialog({
        title: '¡Aviso!',
        message: 'La información en nuestros registros parece estar desactualizada. Por favor, visite una de nuestras agencias para actualizar su información.',
        acceptButton: true,
        cancelButton: false
      }).subscribe( _ => {
        this.store.dispatch( AttemptsActions.incremetAttempts() );
        this.goToStepFour.emit(correct);
      });
      return;
    }
    this.store.dispatch( CustomerActions.sendCode() );
    this.goToStepFour.emit(correct);
  }

}
