import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule } from '@angular/forms';
import { StoreModule } from '@ngrx/store';

import { CheckInformationComponent } from './components/check-information/check-information.component';
import { CheckPhoneComponent } from './components/check-phone/check-phone.component';
import { IdentificationDataComponent } from './components/identification-data/identification-data.component';
import { OtpValidateComponent } from './components/otp-validate/otp-validate.component';
import { VerifyIdentityComponent } from './verify-identity.component';

import { CodeInputModule } from 'angular-code-input';
import { MaterialModule } from '../material/material.module';
import { SharedModule } from '../shared/shared.module';
import { VerifyIdentityRoutingModule } from './verify-identity-routing.module';
import { AttemptsReducer, CustomerReducer } from './store';
import { EffectsModule } from '@ngrx/effects';
import { CustomerEffects } from './store/effects/customer.effects';
import { AttemptsEffects } from './store/effects/attempts.effects';
import { RECAPTCHA_LANGUAGE, RECAPTCHA_V3_SITE_KEY, RecaptchaV3Module } from "ng-recaptcha";
import { environment } from '../../environments/environment';

@NgModule({
  declarations: [
    CheckInformationComponent,
    CheckPhoneComponent,
    IdentificationDataComponent,
    OtpValidateComponent,
    VerifyIdentityComponent
  ],
  imports: [
    CommonModule,
    ReactiveFormsModule,
    StoreModule.forFeature( AttemptsReducer.actionReducerAttemptsKey, AttemptsReducer.attemptsReducer ),
    StoreModule.forFeature( CustomerReducer.actionReducerCustomerKey, CustomerReducer.customerReducer),
    EffectsModule.forFeature([ CustomerEffects, AttemptsEffects ]),
    CodeInputModule.forRoot({
      codeLength: 6,
      isCharsCode: true,
      code: ''
    }),
    VerifyIdentityRoutingModule,
    SharedModule,
    MaterialModule,
    RecaptchaV3Module
  ],
  providers: [
    { provide: RECAPTCHA_V3_SITE_KEY, useValue: environment.RECAPTCHA.SITE_KEY },
    { provide: RECAPTCHA_LANGUAGE, useValue: environment.RECAPTCHA.LANGUAGE },
  ],
})
export class VerifyIdentityModule { }
