import { Injectable } from '@angular/core';
import { AbstractControl, ValidationErrors } from '@angular/forms';

@Injectable({
  providedIn: 'root'
})
export class ValidatorsService {

  public validateBirthday(control: AbstractControl): ValidationErrors | null {
    const value = control.value;
    if (!value) {
      return null;
    }

    const birthdate = new Date(value);
    const today = new Date();
    if (birthdate >= today) {
      return { invalidBirthdate: 'La fecha de nacimiento debe ser anterior a la fecha actual.' };
    }

    const minAge = 17;
    const maxDate = new Date(today.getFullYear() - minAge, today.getMonth(), today.getDate());
    if (birthdate > maxDate) {
      return { invalidBirthdate: 'La fecha de nacimiento es de un menor de edad.' };
    }

    const maxAge = 100;
    const minDate = new Date(today.getFullYear() - maxAge, today.getMonth(), today.getDate());
    if (birthdate < minDate) {
      return { invalidBirthdate: 'La fecha de nacimiento es demasiado antigua.' };
    }

    return null;
  }

  public validateNullValue(control: AbstractControl): ValidationErrors | null {
    return control.value === null ? { nullValue: 'Por favor, complete el campo requerido' } : null;
  }

}
